void need(bool value,const char* message){if(!value)throw std::runtime_error(message);}
mu::client::Character fixture(unsigned cls,unsigned tier){mu::client::Character c{};c.name="Resource";c.appearance.assign(18,255);c.appearance[0]=(cls<<5)|(tier==2?31:tier==1?16:0);c.appearance[5]=0xF3;c.appearance[9]=0xF8;c.appearance[10]=c.appearance[11]=c.appearance[16]=c.appearance[17]=0;c.appearance[12]=0xF0;return c;}
int main(int argc,char** argv){try{need(argc==2,"Usage: character_resources_test CLIENT_ROOT");unsigned variants=0;for(unsigned cls=0;cls<7;cls++)for(unsigned tier=0;tier<3;tier++){if(tier==1&&(cls==3||cls==4||cls==6))continue;auto c=fixture(cls,tier);auto r=mu::viewer::character_resources(c);need(r.baseClass==cls&&r.tier==tier,"CharSet class/tier decode failed");for(unsigned type:r.armor)need(type==511,"Unarmored CharSet decoded armor");auto body=mu::viewer::load_character_body(argv[1],r);need(!body->meshes.empty()&&!body->idle.empty()&&!body->walk.empty()&&!body->run.empty(),"Class body or motion missing");need(body==mu::viewer::load_character_body(argv[1],r),"Body cache did not reuse resources");mu::client::CharacterList list{};list.characters.push_back(c);auto lobby=mu::lobby::load_characters(argv[1],list);need(lobby.size()==1&&lobby[0].visual->parts.size()==body->meshes.size(),"Selection/world body differs");variants++;}
 // A +9 torso must retain its grade through CharSet -> body -> lobby -> GPU passes.
 for(unsigned level:{0u,3u,5u,7u,9u,11u,13u,15u}){auto preview=fixture(0,0);preview.appearance[3]=0xF3;preview.appearance[9]&=~64;preview.appearance[14]&=15;unsigned grade=level?(level-1)/2:0,packed=grade<<9;preview.appearance[6]=packed>>16;preview.appearance[7]=packed>>8;preview.appearance[8]=packed;preview.appearance[10]=64;auto decoded=mu::viewer::character_resources(preview);need(decoded.armorItems[1]&&decoded.armorItems[1]->level==level&&decoded.armorItems[1]->excellent,"Lobby CharSet grade/excellent lost");mu::client::CharacterList list;list.characters.push_back(preview);auto lobby=mu::lobby::load_characters(argv[1],list);bool retained=false;for(auto& part:lobby[0].visual->parts)if(part.equipment){need(part.equipment->level==level,"Selection dropped armor grade");retained=true;}need(retained&&lobby[0].visual->effectDirectory==std::filesystem::path(argv[1])/"Data","Selection lost effect metadata/path");auto rig=[[MuCharacterRig alloc] initWithVisual:lobby[0].visual];unsigned additive=0;std::function<void(SCNNode*)> count=[&](SCNNode* node){for(SCNMaterial* material in node.geometry.materials)if(material.blendMode==SCNBlendModeAdd)additive++;for(SCNNode* child in node.childNodes)count(child);};count(rig.node);need(level>=7?additive>0:additive==0,"Selection upgrade passes differ from world policy");}
 {auto c=fixture(0,0);unsigned right=5*512+3,left=6*512+1;c.appearance[1]=right&255;c.appearance[12]=(c.appearance[12]&15)|((right>>4)&240);c.appearance[2]=left&255;c.appearance[13]=(c.appearance[13]&15)|((left>>4)&240);unsigned levels=4|(7<<3);c.appearance[6]=levels>>16;c.appearance[7]=levels>>8;c.appearance[8]=levels;c.appearance[10]=4;c.appearance[11]=2;auto r=mu::viewer::character_resources(c);need(r.attachments[0]&&r.attachments[0]->index==right&&r.attachments[0]->level==9&&r.attachments[0]->excellent,"Right-hand CharSet preview missing or wrong");need(r.attachments[1]&&r.attachments[1]->index==left&&r.attachments[1]->level==15&&r.attachments[1]->setOption,"Left-hand CharSet preview missing or wrong");mu::client::CharacterList list;list.characters.push_back(c);auto preview=mu::lobby::load_characters(argv[1],list);need(preview[0].visual->links.size()==2,"Lobby dropped worn weapons");auto rig=[[MuCharacterRig alloc] initWithVisual:preview[0].visual];[rig advance:.2];need([rig.node childNodeWithName:@"worn:0" recursively:YES]!=nil&&[rig.node childNodeWithName:@"worn:1" recursively:YES]!=nil,"Lobby hand attachments missing");mu::client::InventorySnapshot empty;empty.ready=true;auto authoritative=mu::viewer::character_resources(c,&empty);need(!authoritative.attachments[0]&&!authoritative.attachments[1],"Empty authoritative hands retained stale CharSet weapon");}
 auto catalog=mu::ui::load_item_catalog(std::filesystem::path(argv[1])/"Data","Eng");auto stance=mu::viewer::base_character_resources(0);mu::client::Item blade;blade.index=0;stance.attachments[0]=blade;need(mu::viewer::equipped_actions(stance,*catalog)==std::array<unsigned,3>{4,17,26},"One-hand source actions differ");stance.attachments[1]=blade;need(mu::viewer::equipped_actions(stance,*catalog)[2]==27,"Dual sword run action differs");stance.attachments[0]->index=5*512+14;need(mu::viewer::equipped_actions(stance,*catalog)==std::array<unsigned,3>{10,23,32},"Summoner wand actions differ");stance.attachments[0].reset();stance.attachments[1]->index=4*512;need(mu::viewer::equipped_actions(stance,*catalog)==std::array<unsigned,3>{8,21,30},"Left-hand bow actions differ");stance.attachments[1].reset();blade.index=4*512+8;stance.attachments[0]=blade;need(mu::viewer::equipped_actions(stance,*catalog)==std::array<unsigned,3>{9,22,31},"Right-hand crossbow actions differ");
 auto c=fixture(0,0);mu::client::InventorySnapshot inventory;inventory.ready=true;mu::client::Item armor;armor.index=8*512;inventory.items[3]=armor;auto r=mu::viewer::character_resources(c,&inventory);need(r.models[1]=="ArmorMale01.bmd"&&r.models[0]=="HelmClass01.bmd","Server equipment did not override CharSet/body");auto equipped=mu::viewer::load_character_body(argv[1],r);need(!equipped->meshes.empty(),"Equipped armor mesh missing");need(r.key()!=mu::viewer::base_character_resources(0).key(),"Equipment collides with base-body cache");
 auto levelKey=r.key();inventory.items[3].level=15;auto upgraded=mu::viewer::character_resources(c,&inventory);need(upgraded.key()!=levelKey,"Armor upgrade collides with body cache");auto glowing=mu::viewer::load_character_body(argv[1],upgraded);bool metadata=false;for(const auto& mesh:glowing->meshes)if(mesh.part==1){need(mesh.equipment&&mesh.equipment->level==15,"Equipped level lost before renderer");metadata=true;}need(metadata,"Equipped torso missing");
 mu::client::Item staff;staff.index=5*512;staff.level=15;inventory.items[0]=staff;mu::client::Item shield;shield.index=6*512;shield.level=9;inventory.items[1]=shield;mu::client::Item wings;wings.index=12*512+1;inventory.items[7]=wings;auto attached=mu::viewer::character_resources(c,&inventory);need(attached.key()!=upgraded.key(),"Attachment cache key lost equipment");auto attachedBody=mu::viewer::load_character_body(argv[1],attached);need(attachedBody->attachments.size()==3,"Weapon/shield/wing model missing");for(auto& part:attachedBody->attachments)need(!part.visual->parts.empty()&&!part.visual->idle.empty(),"Attachment geometry or animation missing");need(attachedBody->combatActions[0]==(mu::ui::load_item_catalog(std::filesystem::path(argv[1])/"Data","Eng")->at(staff.index).twoHand?7u:4u),"Staff held stance differs from source");inventory.items.erase(0);inventory.items.erase(1);inventory.items.erase(7);
 inventory.items[3].index=7*512;bool failed=false;try{mu::viewer::character_resources(c,&inventory);}catch(const std::exception&){failed=true;}need(failed,"Wrong slot group accepted");
