 for(auto test:std::array<std::array<unsigned,3>,3>{{{{5,1,10}},{{4,0,5}},{{6,4,6}}}}){auto character=fixture(test[0],0);mu::client::InventorySnapshot inv;inv.ready=true;mu::client::Item item;item.index=(test[1]+7)*512+test[2];inv.items[test[1]+2]=item;auto resource=mu::viewer::character_resources(character,&inv);need(!mu::viewer::load_character_body(argv[1],resource)->meshes.empty(),"Special class equipped model failed original bone binding");}
 std::cout<<"PASS: "<<variants<<" original class/tier bodies, shared selection/world meshes, animation clips, authoritative armor slots and bounded body cache.\n";return 0;
 }catch(const std::exception& e){std::cerr<<e.what()<<"\n";return 1;}}
